<script setup>
import { ref, nextTick, watch } from 'vue'
const props = defineProps({ user: Object, households: Array, selectedId: String, loading: Boolean, saving: Boolean, error: String })
const emit = defineEmits(['create', 'retry', 'logout'])
const showCreate = ref(false), name = ref(''), field = ref(null), trigger = ref(null), dialog = ref(null)
watch(showCreate, async open => { await nextTick(); (open ? field.value : trigger.value)?.focus() })
watch(() => props.selectedId, () => { showCreate.value = false; name.value = '' })
function trap(event) {
  if (event.key !== 'Tab') return
  const controls = [...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled)')]
  const first = controls[0], last = controls.at(-1)
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
}
const memberCount = house => house.memberUserIds?.length || 0
</script>
<template>
  <div class="account-workspace"><aside class="account-sidebar"><a class="account-brand" href="#home"><span>f</span>fairshare</a><p class="account-eyebrow">YOUR SPACE</p><a class="account-nav" href="#households">⌂ My households <span>{{ households.length }}</span></a><div class="account-profile"><strong>{{ user.email }}</strong><small>Signed in</small></div><button class="account-logout" @click="emit('logout')">Log out ↗</button></aside>
    <main class="account-main"><header class="account-top">My space <span>Shared living, organized.</span></header><section class="account-content"><a v-if="selectedId" href="#households" class="account-back">← All households</a><div class="account-heading"><div><p class="account-eyebrow">YOUR SHARED SPACE</p><h1>{{ selectedId ? households.find(h => h.id === selectedId)?.name || 'Household' : 'Welcome home.' }}</h1><p class="account-muted">{{ selectedId ? 'Household information saved for your account.' : 'Your people. Your shared spaces. All together.' }}</p></div><button v-if="!selectedId" ref="trigger" class="account-button account-primary" @click="showCreate = true">+ Create household</button></div>
      <p v-if="error && !showCreate" class="account-error" role="alert">{{ error }} <button class="account-text-button" @click="emit('retry')">Try again</button></p><p v-if="loading" role="status">Loading your households…</p>
      <template v-else-if="selectedId"><template v-for="house in households.filter(h => h.id === selectedId)" :key="house.id"><div class="account-stats"><article><span>MEMBERS</span><strong>{{ memberCount(house) }}</strong></article><article><span>YOUR ROLE</span><strong>{{ house.ownerUserId === user.id ? 'Owner' : 'Member' }}</strong></article><article><span>CREATED</span><strong>{{ new Date(house.createdAt).toLocaleDateString() }}</strong></article></div><div class="account-panel"><h2>Household members</h2><p class="account-help">The current API returns member IDs, rather than names. Invitations and member profiles are separate work.</p><div v-for="id in house.memberUserIds" :key="id" class="account-member"><strong>{{ id === user.id ? user.email + ' (you)' : 'Household member' }}</strong><code>{{ id }}</code><span>{{ id === house.ownerUserId ? 'Owner' : 'Member' }}</span></div></div><p class="account-help">Inventory, invitations and expenses are not connected on this screen yet.</p></template><div v-if="!households.some(h => h.id === selectedId) && !error" class="account-empty"><h2>Household unavailable</h2><p>This household is not in your account’s list.</p><a href="#households" class="account-button account-primary">My households</a></div></template>
      <template v-else><h2 class="account-section-title">My households <small>{{ households.length }}</small></h2><div v-if="households.length" class="account-house-grid"><a v-for="house in households" :key="house.id" :href="'#household/' + house.id" class="account-house-card"><div><span class="account-house-icon">⌂</span><span class="account-role">{{ house.ownerUserId === user.id ? 'Owner' : 'Member' }}</span></div><h3>{{ house.name }}</h3><p>{{ memberCount(house) }} {{ memberCount(house) === 1 ? 'member' : 'members' }}</p><footer>Open household <span>↗</span></footer></a></div><div v-else-if="!error" class="account-empty"><h2>A place to start.</h2><p>You don’t belong to a household yet. Create one to get started.</p><button class="account-button account-primary" @click="showCreate = true">Create your first household</button></div></template>
    </section><footer class="account-footer">© 2026 FairShare <span>Less struggle. More saving.</span></footer></main>
    <div v-if="showCreate" class="account-overlay" @click.self="!saving && (showCreate = false)"><section ref="dialog" class="account-dialog" role="dialog" aria-modal="true" aria-labelledby="create-title" @keydown="trap" @keydown.esc="!saving && (showCreate = false)"><button class="account-close" aria-label="Close" :disabled="saving" @click="showCreate = false">×</button><p class="account-eyebrow">A NEW SHARED SPACE</p><h2 id="create-title">Make yourself at home.</h2><p class="account-muted">Give your household a name. You’ll be its first member and owner.</p><form @submit.prevent="emit('create', name)"><label>Household name<input ref="field" v-model="name" required maxlength="100" :disabled="saving" placeholder="e.g. Our Apartment" /></label><p v-if="error" class="account-error" role="alert">{{ error }}</p><div class="account-dialog-actions"><button type="button" class="account-button account-secondary" :disabled="saving" @click="showCreate = false">Cancel</button><button class="account-button account-primary" :disabled="saving">{{ saving ? 'Creating…' : 'Create household →' }}</button></div></form></section></div>
  </div>
</template>
